import { describe, expect, it } from "vitest";
import { hasWithSpanModelCall, WITHSPAN_MODEL_FRAMEWORKS, } from "./frameworks.js";
describe("WITHSPAN_MODEL_FRAMEWORKS", () => {
    it("exempts the Vercel AI SDK under both the registry id and the analyzer alias", () => {
        expect(WITHSPAN_MODEL_FRAMEWORKS.has("vercel-ai-sdk")).toBe(true);
        expect(WITHSPAN_MODEL_FRAMEWORKS.has("vercel")).toBe(true);
    });
    it("does not exempt observe-only frameworks", () => {
        for (const id of [
            "langgraph",
            "langchain",
            "openai-agents",
            "claude-agent-sdk",
            "baml",
        ]) {
            expect(WITHSPAN_MODEL_FRAMEWORKS.has(id), id).toBe(false);
        }
    });
});
describe("hasWithSpanModelCall", () => {
    it("is false for an untagged span", () => {
        expect(hasWithSpanModelCall(undefined)).toBe(false);
    });
    it("is false for a framework that is not wrap-based", () => {
        expect(hasWithSpanModelCall("langgraph")).toBe(false);
    });
    it("is true for a wrap-based framework", () => {
        expect(hasWithSpanModelCall("vercel-ai-sdk")).toBe(true);
        expect(hasWithSpanModelCall("vercel")).toBe(true);
    });
    it("is false for an unknown framework rather than throwing", () => {
        expect(hasWithSpanModelCall("not-a-real-framework")).toBe(false);
    });
});
